namespace Tsumo.Tests
{
    public static class Node_modules_Tsumo_engine_src_template_evaluation_paramSemantics
    {
        public static TemplateValue paramToTemplateValue(ParamValue value)
        {
            if (value.kind == ParamKind.Bool)
            {
                return new BoolValue(value.boolValue);
            }
            if (value.kind == ParamKind.Number)
            {
                return new NumberValue(value.numberValue);
            }
            return new StringValue(value.stringValue);
        }
        public static ParamValue? findParam(Tsonic.CSharp.Js.Map<string, ParamValue> values, string name)
        {
            ParamValue? exact = Tsonic.CSharp.Js.Map.getOptional<string, ParamValue>(values, name);
            if (exact is not null)
            {
                return exact;
            }
            string normalized = Tsonic.CSharp.Js.String.toLowerCase(name);
            foreach (string key in values.keys())
            {
                if (Tsonic.CSharp.Js.String.toLowerCase(key) == normalized)
                {
                    return Tsonic.CSharp.Js.Map.getOptional<string, ParamValue>(values, key);
                }
            }
            return null;
        }
        private static readonly System.Lazy<object?> __tsonic_module_initialization = new System.Lazy<object?>(() => __tsonic_module_init_core());
        private static object? __tsonic_module_init_core()
        {
            Node_modules_Tsumo_engine_src_params.__tsonic_module_init();
            Node_modules_Tsumo_engine_src_template_values.__tsonic_module_init();
            return null;
        }
        public static void __tsonic_module_init()
        {
            _ = __tsonic_module_initialization.Value;
        }
    }
